import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Telegram","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/telegram.md","filePath":"zh/integrations/channels/telegram.md","lastUpdated":1790952322000}'),l={name:"zh/integrations/channels/telegram.md"};function n(h,e,i,s,d,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h1><p>把 Memoh Bot 接到 Telegram。Memoh 对 Telegram 的支持较全：流式、Markdown、附件等。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>一个 Telegram 账号，用于和 <strong>@BotFather</strong> 对话建 Bot。</li><li>一个 Memoh Bot；渠道在它的 <strong>平台</strong> 标签页里配置。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在-telegram-用-botfather-创建-bot" tabindex="-1">1. 在 Telegram 用 @BotFather 创建 Bot <a class="header-anchor" href="#_1-在-telegram-用-botfather-创建-bot" aria-label="Permalink to &quot;1. 在 Telegram 用 @BotFather 创建 Bot&quot;">​</a></h3><ol><li>在 Telegram 里搜索官方 <strong>@BotFather</strong>。</li><li>发送 <code>/newbot</code>。</li><li>按提示填写： <ul><li><strong>Name</strong>：展示名，如 <code>My Memoh Bot</code>。</li><li><strong>Username</strong>：全局唯一、以 <code>bot</code> 结尾，如 <code>my_memoh_bot</code>。</li></ul></li><li>BotFather 会回复 <strong>API Token</strong>（形如 <code>123456789:ABC...</code>）。<strong>不要泄露。</strong></li></ol><blockquote><p>官方说明：<a href="https://core.telegram.org/bots/tutorial" target="_blank" rel="noreferrer">Telegram Bot Tutorial</a></p></blockquote><h3 id="_2-在-memoh-添加-telegram-渠道" tabindex="-1">2. 在 Memoh 添加 Telegram 渠道 <a class="header-anchor" href="#_2-在-memoh-添加-telegram-渠道" aria-label="Permalink to &quot;2. 在 Memoh 添加 Telegram 渠道&quot;">​</a></h3><ol><li>打开 Bot 详情页，进入 <strong>平台</strong> 标签页。</li><li>点 <strong>Add Channel</strong>，选 <strong>Telegram</strong>。</li><li>把 <strong>API Token</strong> 填进凭据字段。</li><li>点 <strong>Save and Enable</strong>。</li></ol><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>API Token</strong></td><td>创建 Bot 时 BotFather 发给你的 token（形如 <code>123456789:ABC...</code>），不要泄露。</td></tr></tbody></table><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>在 Telegram 里私聊 Bot，发送 <code>/help</code>。Bot 回复命令列表即说明渠道已生效。</p><h2 id="群聊" tabindex="-1">群聊 <a class="header-anchor" href="#群聊" aria-label="Permalink to &quot;群聊&quot;">​</a></h2><p>Telegram 支持群聊。把 Bot 拉进群后，@它的用户名即可在群里对话。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>在 Bot 的 <strong>平台</strong> 标签页可以随时停用或移除该渠道。更换 token 时，更新 <strong>API Token</strong> 字段并保存即可。</p>',18)])])}const b=t(l,[["render",n]]);export{c as __pageData,b as default};
